class ThemeManager{constructor(){if(ThemeManager.instance){return ThemeManager.instance;}this.themes=['light','dark','auto'];this.currentTheme=this.getInitialTheme();this.mediaQuery=window.matchMedia('(prefers-color-scheme:dark)');ThemeManager.instance=this;this.init();}init(){this.applyTheme();this.listenForSystemChanges();window.themeManager=this;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=> this.updateToggleButton());}else{this.updateToggleButton();}}getInitialTheme(){try{const saved=localStorage.getItem('theme');return this.themes.includes(saved)? saved:'auto';}catch(error){console.warn('localStorage not available,using auto theme:',error);return 'auto';}}applyTheme(){const resolvedTheme=this.resolveTheme();if(resolvedTheme==='dark'){document.documentElement.setAttribute('data-theme','dark');}else{document.documentElement.removeAttribute('data-theme');}setTimeout(()=> this.updateToggleButton(),10);this.dispatchThemeChangeEvent();}resolveTheme(){if(this.currentTheme==='auto'){return this.mediaQuery.matches ? 'dark':'light';}return this.currentTheme;}setTheme(theme){if(!this.themes.includes(theme)){console.warn(`Invalid theme:${theme}. Valid themes:`,this.themes);return;}this.currentTheme=theme;try{localStorage.setItem('theme',theme);}catch(error){console.warn('Failed to persist theme preference:',error);}this.applyTheme();}toggleTheme(){const resolved=this.resolveTheme();const newTheme=resolved==='dark' ? 'light':'dark';this.setTheme(newTheme);}getThemeInfo(){return{current:this.currentTheme,resolved:this.resolveTheme(),isAuto:this.currentTheme==='auto',systemPrefersDark:this.mediaQuery.matches};}listenForSystemChanges(){this.mediaQuery.addEventListener('change',(e)=>{console.log('System theme preference changed to:',e.matches ? 'dark':'light');if(this.currentTheme==='auto'){this.applyTheme();}});}updateToggleButton(){const button=document.getElementById('dark-mode-toggle');if(!button)return;const icon=button.querySelector('i');if(!icon)return;const resolved=this.resolveTheme();const isAuto=this.currentTheme==='auto';if(isAuto){icon.className=`fas fa-adjust`;}else{icon.className=`fas ${resolved==='dark' ? 'fa-sun':'fa-moon'}`;}const modeText=isAuto ? 'auto':resolved;const nextMode=resolved==='dark' ? 'light':'dark';button.setAttribute('aria-label',`Current theme:${modeText}. Click to switch to ${nextMode}mode`);button.setAttribute('aria-pressed',resolved==='dark');button.setAttribute('title',isAuto ? `Auto theme(currently ${resolved})`:`${resolved}theme`);}dispatchThemeChangeEvent(){const event=new CustomEvent('themeChanged',{detail:{theme:this.currentTheme,resolved:this.resolveTheme(),isAuto:this.currentTheme==='auto',timestamp:Date.now()}});window.dispatchEvent(event);}enableTransitions(){const style=document.createElement('style');style.id='theme-transitions';style.textContent=`*{transition:background-color 0.3s ease,border-color 0.3s ease,color 0.3s ease,box-shadow 0.3s ease !important;}@media(prefers-reduced-motion:reduce){*{transition-duration:0.01ms !important;}}`;document.head.appendChild(style);setTimeout(()=>{const transitionStyle=document.getElementById('theme-transitions');if(transitionStyle){transitionStyle.remove();}},300);}destroy(){this.mediaQuery.removeEventListener('change',this.listenForSystemChanges);delete window.themeManager;}debug(){return{themes:this.themes,current:this.currentTheme,resolved:this.resolveTheme(),systemPrefersDark:this.mediaQuery.matches,localStorage:this.getStoredTheme(),documentTheme:document.documentElement.getAttribute('data-theme')};}getStoredTheme(){try{return localStorage.getItem('theme');}catch{return null;}}}export default ThemeManager;